import React, { useState, useEffect } from 'react'
import { View, Text, Image, TouchableOpacity, Modal, Alert, Platform, PermissionsAndroid, Dimensions } from 'react-native'
import ImagePicker from 'react-native-image-crop-picker';
import { FontAwesome } from '@react-native-vector-icons/fontawesome';
import Lightbox from 'react-native-lightbox-v2';
import { launchCamera, launchImageLibrary, MediaType, ImagePickerResponse } from 'react-native-image-picker';
import { useDispatch } from 'react-redux';
import { style } from './style'
import { TomarFotoProps, ImagenData } from './tomarFoto.types'
import { uploadMultipleImagesToS3 } from '../../redux/actions/reporteActions'

const TomarFoto: React.FC<TomarFotoProps> = ({
    source = [],
    width,
    titulo,
    descripcion,
    multiple = false,
    limiteImagenes = 4,
    imagenes,
    avatar,
    tipoMensaje,
    cerrar,
    soloLectura = false,
    mostrarSoloConImagenes = false,
    permitirSubir = true,
    onUploadComplete
}) => {
    const dispatch = useDispatch();
    const [imagenesState, setImagenesState] = useState<any[]>(source);
    const [showModal, setShowModal] = useState(false);
    const [isAndroidShareOpen, setIsAndroidShareOpen] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const [pendingUpdates, setPendingUpdates] = useState<{ imageData: any[], urls: string[] } | null>(null);
    const [expandedImageIndex, setExpandedImageIndex] = useState<number | null>(null);

    // Sincronizar el estado interno con el prop source cuando cambie
    // Solo sincronizar si no estamos en modo múltiple
    useEffect(() => {
        if (!multiple) {
            console.log('🔄 [TomarFoto] Sincronizando con source (modo single):', source);
            setImagenesState(source);
        } else {
            console.log('🔄 [TomarFoto] Ignorando sincronización con source en modo múltiple:', source);
        }
    }, [source, multiple]);

    // Effect para limpiar imágenes cuando source está vacío en modo múltiple
    useEffect(() => {
        if (multiple && source.length === 0 && imagenesState.length > 0) {
            console.log('🧹 [TomarFoto] Limpiando imágenes porque source está vacío en modo múltiple');
            setImagenesState([]);
        }
    }, [source, multiple, imagenesState.length]);

    // Manejar actualizaciones pendientes de S3
    useEffect(() => {
        if (pendingUpdates) {
            const { imageData, urls } = pendingUpdates;
            console.log('🔄 [TomarFoto] Procesando actualizaciones pendientes:', { imageData, urls });

            if (multiple) {
                // En modo múltiple, actualizar solo las URLs de S3 de las imágenes subidas
                console.log('🔄 [TomarFoto] Modo múltiple - actualizando URLs de S3');
                setImagenesState(prevImages => {
                    const updatedImages = [...prevImages];

                    // Para cada imagen que se subió, actualizar su URL de S3
                    imageData.forEach((img, index) => {
                        const existingIndex = updatedImages.findIndex(existingImg =>
                            existingImg.uri === img.uri || existingImg.base64 === img.base64
                        );

                        if (existingIndex !== -1) {
                            // Solo actualizar la URL de S3, mantener todo lo demás
                            updatedImages[existingIndex] = {
                                ...updatedImages[existingIndex],
                                uri: urls[index] || updatedImages[existingIndex].uri, // Usar URL de S3 si está disponible
                                s3Url: urls[index] // Guardar la URL de S3
                            };
                            console.log(`🔄 [TomarFoto] Imagen ${existingIndex} actualizada con URL S3:`, updatedImages[existingIndex]);
                        } else {
                            // Si no se encuentra la imagen, agregarla (por si acaso)
                            console.log('⚠️ [TomarFoto] Imagen no encontrada en estado, agregando:', img);
                            updatedImages.push({
                                ...img,
                                uri: urls[index] || img.uri,
                                s3Url: urls[index]
                            });
                        }
                    });

                    console.log('🔄 [TomarFoto] Estado final después de actualizar URLs S3:', updatedImages);

                    // Notificar al componente padre con el estado actualizado
                    setTimeout(() => {
                        imagenes?.(updatedImages);
                    }, 0);

                    return updatedImages;
                });
            } else {
                // En modo single, reemplazar todo el estado
                const updatedImages = imageData.map((img, index) => ({
                    ...img,
                    uri: urls[index] || img.uri,
                    s3Url: urls[index]
                }));
                console.log('🔄 [TomarFoto] Estado actualizado en modo single:', updatedImages);
                setImagenesState(updatedImages);
                imagenes?.(updatedImages);
            }

            setPendingUpdates(null);
        }
    }, [pendingUpdates, multiple, imagenes]);

    // Función para subir imágenes a S3
    const uploadImagesToS3 = async (images: any[]) => {
        console.log('📸 [TomarFoto] uploadImagesToS3 llamada con:', images.length, 'imágenes');
        console.log('📸 [TomarFoto] onUploadComplete disponible:', !!onUploadComplete);
        console.log('📸 [TomarFoto] permitirSubir:', permitirSubir);

        if (!onUploadComplete || images.length === 0) {
            console.log('⚠️ [TomarFoto] No se puede subir - onUploadComplete:', !!onUploadComplete, 'images.length:', images.length);
            return;
        }

        try {
            console.log('🔄 [TomarFoto] Iniciando subida de imágenes...');
            setIsUploading(true);
            const imageData = images.map(img => ({
                uri: img.uri || img,
                base64: img.base64
            }));
            console.log('📸 [TomarFoto] Image data extraída:', imageData.map(img => ({
                uri: img.uri,
                hasBase64: !!img.base64
            })));

            const result = await dispatch(uploadMultipleImagesToS3(imageData) as any);
            const urls = Array.isArray(result) ? result : [];
            console.log('✅ [TomarFoto] URLs obtenidas:', urls);

            // Establecer actualizaciones pendientes para que el useEffect las procese
            console.log('🔄 [TomarFoto] Estableciendo actualizaciones pendientes:', { imageData, urls });
            setPendingUpdates({ imageData, urls });

            onUploadComplete(urls);
            console.log('✅ [TomarFoto] onUploadComplete ejecutado con URLs');
        } catch (error) {
            console.error('❌ [TomarFoto] Error uploading images to S3:', error);
            Alert.alert('Error', 'No se pudieron subir las imágenes. Inténtalo de nuevo.');
        } finally {
            console.log('🔄 [TomarFoto] Finalizando subida, isUploading = false');
            setIsUploading(false);
        }
    };
    // Función para solicitar permisos de cámara
    const requestCameraPermission = async (): Promise<boolean> => {
        if (Platform.OS === 'android') {
            try {
                const granted = await PermissionsAndroid.request(
                    PermissionsAndroid.PERMISSIONS.CAMERA,
                    {
                        title: 'Permiso de Cámara',
                        message: 'Esta aplicación necesita acceso a la cámara para tomar fotos',
                        buttonNeutral: 'Preguntar después',
                        buttonNegative: 'Cancelar',
                        buttonPositive: 'OK',
                    }
                );
                return granted === PermissionsAndroid.RESULTS.GRANTED;
            } catch (err) {
                console.warn('Error solicitando permiso de cámara:', err);
                return false;
            }
        }
        return true; // iOS maneja permisos automáticamente
    }

    // Función para abrir cámara usando react-native-image-picker
    const openCamera = async () => {
        const hasPermission = await requestCameraPermission();
        if (!hasPermission) {
            Alert.alert('Error', 'Se necesita permiso de cámara para tomar fotos');
            return;
        }

        const options = {
            mediaType: 'photo' as MediaType,
            quality: 0.8 as any,
            maxWidth: 800,
            maxHeight: 600,
            includeBase64: true,
            saveToPhotos: false,
        };

        launchCamera(options, (response: ImagePickerResponse) => {

            if (response.didCancel) {
                return;
            }

            if (response.errorMessage) {
                console.error('📷 Error de cámara:', response.errorMessage);
                Alert.alert('Error', `Error al abrir cámara: ${response.errorMessage}`);
                return;
            }

            if (response.assets && response.assets[0] && response.assets[0].uri) {
                const asset = response.assets[0];
                handleImageSelected(asset.uri, asset.base64 ?? '');
                Alert.alert('Éxito', 'Foto tomada correctamente');
            }
        });
    }

    // Función para abrir galería usando react-native-image-picker
    const openGallery = () => {
        const options = {
            mediaType: 'photo' as MediaType,
            quality: 0.8 as any,
            maxWidth: 800,
            maxHeight: 600,
            includeBase64: true,
            selectionLimit: multiple ? 4 : 1,
        };

        launchImageLibrary(options, (response: ImagePickerResponse) => {

            if (response.didCancel) {
                return;
            }

            if (response.errorMessage) {
                console.error('🖼️ Error de galería:', response.errorMessage);
                Alert.alert('Error', `Error al abrir galería: ${response.errorMessage}`);
                return;
            }

            if (response.assets && response.assets.length > 0) {
                if (multiple) {
                    response.assets.forEach(asset => {
                        if (asset.uri) {
                            handleImageSelected(asset.uri, asset.base64 ?? '');
                        }
                    });
                } else {
                    if (response.assets[0].uri) {
                        handleImageSelected(response.assets[0].uri, response.assets[0].base64 ?? '');
                    }
                }
            }
        });
    }

    // Función para manejar la imagen seleccionada
    const handleImageSelected = (imageUri: string, base64Data: string = '') => {
        console.log('📸 [TomarFoto] handleImageSelected llamada con URI:', imageUri);
        console.log('📸 [TomarFoto] Base64 disponible:', !!base64Data);
        console.log('📸 [TomarFoto] multiple:', multiple, 'permitirSubir:', permitirSubir, 'onUploadComplete:', !!onUploadComplete);

        // Si no es múltiple, limpiar imágenes anteriores
        if (!multiple) {
            console.log('📸 [TomarFoto] Modo single - limpiando imágenes anteriores');
            const newImage = { uri: imageUri, base64: base64Data };
            setImagenesState([newImage]);
            imagenes?.([newImage]);
            // Subir a S3 si está habilitado
            if (permitirSubir && onUploadComplete) {
                console.log('📸 [TomarFoto] Iniciando subida para imagen única');
                uploadImagesToS3([newImage]);
            } else {
                console.log('⚠️ [TomarFoto] No se subirá - permitirSubir:', permitirSubir, 'onUploadComplete:', !!onUploadComplete);
            }
        } else {
            // Si es múltiple, agregar a la lista
            console.log('📸 [TomarFoto] Modo múltiple - agregando a lista');
            console.log('📸 [TomarFoto] Estado actual antes de agregar:', imagenesState);
            console.log('📸 [TomarFoto] Cantidad actual de imágenes:', imagenesState.length);
            if (imagenesState.length < limiteImagenes) {
                const newImage = { uri: imageUri, base64: base64Data };
                const newImagenes = [...imagenesState, newImage];
                console.log('📸 [TomarFoto] Agregando nueva imagen:', newImage);
                console.log('📸 [TomarFoto] Nuevo estado después de agregar:', newImagenes);
                console.log('📸 [TomarFoto] Cantidad después de agregar:', newImagenes.length);
                setImagenesState(newImagenes);
                imagenes?.(newImagenes);
                // Subir a S3 si está habilitado - solo la nueva imagen
                if (permitirSubir && onUploadComplete) {
                    console.log('📸 [TomarFoto] Iniciando subida para imagen individual en modo múltiple');
                    uploadImagesToS3([newImage]);
                } else {
                    console.log('⚠️ [TomarFoto] No se subirá - permitirSubir:', permitirSubir, 'onUploadComplete:', !!onUploadComplete);
                }
            } else {
                console.log('⚠️ [TomarFoto] Límite de imágenes alcanzado');
                Alert.alert('Límite alcanzado', `Solo se pueden subir ${limiteImagenes} imágenes`);
            }
        }
    }

    // Función para manejar la selección de imagen (modal)
    const handleTomarFoto = () => {
        Alert.alert(
            'Seleccionar Imagen',
            'Elige una opción',
            [
                {
                    text: 'Cámara',
                    onPress: openCamera
                },
                {
                    text: 'Galería',
                    onPress: openGallery
                },
                {
                    text: 'Cancelar',
                    style: 'cancel'
                }
            ]
        );
    };

    // Función legacy para compatibilidad
    const subirImagen = async () => {
        const options = {
            compressImageMaxWidth: 900,
            compressImageMaxHeight: 900,
            width: 900,
            height: 900,
            includeBase64: true,
            mediaType: 'photo' as any,
            forgeJpg: true,
        };

        ImagePicker.openPicker(options).then(response => {
            if (response) {
                let base64 = `data:${response.mime};base64,${(response as any).data}`
                let imagen = {
                    uri: response.path,
                    type: response.mime ? response.mime : 'image/jpeg',
                    name: (response as any).fileName ? (response as any).fileName : `imagen.jpg`,
                    path: response.path,
                    imagen: base64
                };

                const newImagenes = [...imagenesState, imagen];
                setImagenesState(newImagenes);
                setShowModal(false);
                setIsAndroidShareOpen(false);
                imagenes?.(imagen);
            }
        });
    }

    const tomarFoto = () => {
        const options = {
            compressImageMaxWidth: 900,
            compressImageMaxHeight: 900,
            width: 900,
            height: 900,
            includeBase64: true,
            mediaType: 'photo' as any,
            forgeJpg: true,
        };
        ImagePicker.openCamera(options).then(response => {
            if (response) {
                let base64 = `data:${response.mime};base64,${(response as any).data}`
                let imagen = {
                    uri: response.path,
                    type: response.mime ? response.mime : 'image/jpeg',
                    name: (response as any).fileName ? (response as any).fileName : `imagen.jpg`,
                    path: response.path
                };
                const newImagenes = [...imagenesState, imagen];
                setImagenesState(newImagenes);
                setShowModal(false);
                setIsAndroidShareOpen(false);
                imagenes?.(base64);
            }
        });
    }
    const renderImagenes = () => {
        let img: any[] = []

        imagenesState.map((e: any) => {
            if (e.uri) {
                img.push(e)
            } else {
                img.push({ uri: e })
            }
        })

        return img.map((e: any, key: number) => {
            return (
                <View key={key} style={{ position: 'relative' }}>
                    <TouchableOpacity onPress={() => {
                        setExpandedImageIndex(key);
                    }}>
                        <Image source={{ uri: e.uri }} style={style.imagenesFotos} resizeMode="cover" />
                    </TouchableOpacity>

                    {/* Icono del ojo para expandir */}
                    <TouchableOpacity
                        style={{
                            position: 'absolute',
                            top: 5,
                            left: 5,
                            backgroundColor: 'rgba(0,0,0,0.7)',
                            borderRadius: 15,
                            width: 30,
                            height: 30,
                            justifyContent: 'center',
                            alignItems: 'center'
                        }}
                        onPress={() => {
                            setExpandedImageIndex(key);
                        }}
                    >
                        <FontAwesome name="eye" style={{ fontSize: 14, color: '#fff' }} />
                    </TouchableOpacity>

                    {!soloLectura && (
                        <FontAwesome name={'trash'} style={style.iconTrash} onPress={() => eliminarImagen(key)} />
                    )}
                </View>
            )
        })
    }

    const eliminarImagen = (keyImagen: number) => {
        Alert.alert(
            'Eliminar Imagen',
            'seguro desea eliminar esta imagen',
            [
                {
                    text: 'Cancelar',
                    style: 'cancel'
                },
                { text: 'Eliminar', onPress: () => eliminar() }
            ],
            { cancelable: false }
        );
        const eliminar = () => {
            let newImagenes = imagenesState.filter((e, key) => { return key != keyImagen })
            setImagenesState(newImagenes)
            imagenes?.(newImagenes)
        }
    }
    const renderModal = () => {
        return (
            <Modal
                transparent
                visible={isAndroidShareOpen}
                animationType="fade"
                onRequestClose={() => { }}
            >
                <TouchableOpacity
                    activeOpacity={1}
                    onPress={() => { tipoMensaje ? cerrar?.() : setIsAndroidShareOpen(false); }}
                    style={style.btnModal}
                >
                    <View style={style.contenedorModal}>
                        <TouchableOpacity style={style.btnOpcionModal} onPress={openGallery}>
                            <Text style={style.textModal}>Subir Imagen</Text>
                        </TouchableOpacity>
                        <TouchableOpacity style={style.btnOpcionModal} onPress={openCamera}>
                            <Text style={style.textModal}>Tomar Foto</Text>
                        </TouchableOpacity>
                    </View>
                </TouchableOpacity>
            </Modal>
        )
    }

    /*
        TIPOMENSAJE == cuando la foto es para el chat, no muestra, la opcion de tomar foto, si no que muestra directamente el modal
    */

    // Debug logs
    console.log('🖼️ [TomarFoto] Renderizando componente con:');
    console.log('  - imagenesState.length:', imagenesState.length);
    console.log('  - imagenesState:', imagenesState);
    console.log('  - source.length:', source.length);
    console.log('  - source:', source);
    console.log('  - permitirSubir:', permitirSubir);
    console.log('  - soloLectura:', soloLectura);
    console.log('  - mostrarSoloConImagenes:', mostrarSoloConImagenes);
    console.log('  - multiple:', multiple);

    return (
        <View style={style.contenedorPortada}>
            {
                showModal
                && renderModal()
            }
            {
                tipoMensaje
                    ? renderModal()
                    : permitirSubir && !soloLectura && !mostrarSoloConImagenes && (multiple ? imagenesState.length < limiteImagenes : true)
                    && <View style={{
                        backgroundColor: '#f8f9fa',
                        borderRadius: 12,
                        padding: 16,
                        marginBottom: 20,
                        alignItems: 'center'
                    }}>
                        <FontAwesome name="camera" style={{ fontSize: 32, color: '#007bff', marginBottom: 8 }} />
                        <Text style={{ fontSize: 16, fontWeight: '600', color: '#333', marginBottom: 8 }}>
                            {titulo || 'Foto'}
                        </Text>
                        <Text style={{ fontSize: 14, color: '#666', textAlign: 'center', marginBottom: 16 }}>
                            {descripcion || 'Tome una foto clara para completar el proceso'}
                        </Text>

                        {!soloLectura && (
                            <TouchableOpacity
                                style={{
                                    backgroundColor: isUploading ? '#6c757d' : '#007bff',
                                    borderRadius: 10,
                                    paddingHorizontal: 20,
                                    paddingVertical: 12,
                                    flexDirection: 'row',
                                    alignItems: 'center',
                                    opacity: isUploading ? 0.7 : 1
                                }}
                                onPress={() => {
                                    if (!isUploading) {
                                        handleTomarFoto();
                                    }
                                }}
                                activeOpacity={0.8}
                                disabled={isUploading}
                            >
                                <FontAwesome
                                    name={isUploading ? "spinner" : "camera"}
                                    style={{
                                        fontSize: 16,
                                        color: '#fff',
                                        marginRight: 8,
                                        ...(isUploading && { transform: [{ rotate: '0deg' }] })
                                    }}
                                />
                                <Text style={{ color: '#fff', fontSize: 16, fontWeight: '600' }}>
                                    {isUploading ? 'Subiendo...' : (multiple ? 'Subir Foto' : (imagenesState.length > 0 ? 'Cambiar Foto' : 'Tomar Foto'))}
                                </Text>
                            </TouchableOpacity>
                        )}

                        {imagenesState.length > 0 && (
                            <View style={{
                                marginTop: 12,
                                alignItems: 'center'
                            }}>
                                {/* Debug logs removidos del JSX */}
                                <View style={{
                                    flexDirection: multiple ? 'row' : 'column',
                                    flexWrap: 'wrap',
                                    justifyContent: 'center',
                                    gap: 8
                                }}>
                                    {imagenesState.map((imagen, index) => {
                                        console.log(`🖼️ [TomarFoto] Renderizando imagen ${index}:`, { uri: imagen.uri, s3Url: imagen.s3Url });
                                        return (
                                            <View key={`${imagen.uri}-${index}`} style={{ position: 'relative' }}>
                                                <TouchableOpacity
                                                    onPress={() => {
                                                        // Mostrar imagen en modal o navegación
                                                        Alert.alert('Imagen', 'Imagen seleccionada');
                                                    }}
                                                >
                                                    <Image
                                                        key={imagen.uri} // Forzar re-renderizado cuando cambie la URI
                                                        source={{ uri: imagen.uri }}
                                                        style={{
                                                            width: multiple ? 100 : 150,
                                                            height: multiple ? 100 : 150,
                                                            borderRadius: 10,
                                                            marginBottom: 8
                                                        }}
                                                        resizeMode="cover"
                                                        onLoad={() => console.log(`✅ [TomarFoto] Imagen ${index} cargada exitosamente con URI:`, imagen.uri)}
                                                        onError={(error) => console.error(`❌ [TomarFoto] Error cargando imagen ${index} con URI:`, imagen.uri, error)}
                                                    />
                                                </TouchableOpacity>

                                                {/* Botón de eliminar */}
                                                {!soloLectura && (
                                                    <TouchableOpacity
                                                        style={{
                                                            position: 'absolute',
                                                            top: 5,
                                                            right: 5,
                                                            backgroundColor: 'rgba(0,0,0,0.7)',
                                                            borderRadius: 15,
                                                            width: 30,
                                                            height: 30,
                                                            justifyContent: 'center',
                                                            alignItems: 'center'
                                                        }}
                                                        onPress={() => eliminarImagen(index)}
                                                    >
                                                        <FontAwesome name="trash" style={{ fontSize: 14, color: '#fff' }} />
                                                    </TouchableOpacity>
                                                )}

                                                {/* Botón de expandir (ojo) */}
                                                {/* <TouchableOpacity
                                                    style={{
                                                        position: 'absolute',
                                                        top: 5,
                                                        left: 5,
                                                        backgroundColor: 'rgba(0,0,0,0.7)',
                                                        borderRadius: 15,
                                                        width: 30,
                                                        height: 30,
                                                        justifyContent: 'center',
                                                        alignItems: 'center'
                                                    }}
                                                    onPress={() => {
                                                        // El Lightbox se activa automáticamente al tocar la imagen
                                                        console.log(`👁️ [TomarFoto] Expandir imagen ${index}`);
                                                    }}
                                                >
                                                    <FontAwesome name="eye" style={{ fontSize: 14, color: '#fff' }} />
                                                </TouchableOpacity> */}
                                            </View>
                                        );
                                    })}
                                </View>

                                <View style={{
                                    backgroundColor: '#d4edda',
                                    borderRadius: 8,
                                    padding: 8,
                                    flexDirection: 'row',
                                    alignItems: 'center'
                                }}>
                                    <FontAwesome name="check" style={{ fontSize: 14, color: '#28a745', marginRight: 8 }} />
                                    <Text style={{ color: '#28a745', fontSize: 14, fontWeight: '500' }}>
                                        {imagenesState.length === 1 ? 'Foto agregada correctamente' : `${imagenesState.length} fotos agregadas correctamente`}
                                    </Text>
                                </View>
                            </View>
                        )}
                    </View>
            }
            {
                !tipoMensaje && mostrarSoloConImagenes && imagenesState.length === 0
                && <View style={{
                    backgroundColor: '#f8f9fa',
                    borderRadius: 12,
                    padding: 16,
                    marginBottom: 20,
                    alignItems: 'center'
                }}>
                    <FontAwesome name="image" style={{ fontSize: 32, color: '#6c757d', marginBottom: 8 }} />
                    <Text style={{ fontSize: 16, fontWeight: '600', color: '#6c757d', marginBottom: 8 }}>
                        No hay imágenes
                    </Text>
                    <Text style={{ fontSize: 14, color: '#6c757d', textAlign: 'center' }}>
                        Las imágenes aparecerán aquí después de tomar las fotos
                    </Text>
                </View>
            }

            {/* Modal para expandir imagen */}
            <Modal
                visible={expandedImageIndex !== null}
                transparent={true}
                animationType="fade"
                onRequestClose={() => setExpandedImageIndex(null)}
            >
                <View style={{
                    flex: 1,
                    backgroundColor: 'rgba(0,0,0,0.9)',
                    justifyContent: 'center',
                    alignItems: 'center'
                }}>
                    <TouchableOpacity
                        style={{
                            position: 'absolute',
                            top: 50,
                            right: 20,
                            backgroundColor: 'rgba(255,255,255,0.2)',
                            borderRadius: 20,
                            width: 40,
                            height: 40,
                            justifyContent: 'center',
                            alignItems: 'center'
                        }}
                        onPress={() => setExpandedImageIndex(null)}
                    >
                        <FontAwesome name="times" style={{ fontSize: 20, color: '#fff' }} />
                    </TouchableOpacity>

                    {expandedImageIndex !== null && imagenesState[expandedImageIndex] && (
                        <Image
                            source={{ uri: imagenesState[expandedImageIndex].uri }}
                            style={{
                                width: Dimensions.get('window').width * 0.9,
                                height: Dimensions.get('window').height * 0.7,
                                resizeMode: 'contain'
                            }}
                        />
                    )}
                </View>
            </Modal>
        </View>
    );
};

export default TomarFoto;